import React from 'react';
import Box from '@mui/material/Box';
import MediaCard from './card';
import { useThemeContext } from './../Burger/themeContext';
import themes from './../Burger/theme'
import Typography from '@mui/joy/Typography';
import { useTranslation } from 'react-i18next';

function MesProjets () {
  const {darkMode} = useThemeContext();
  const { t } = useTranslation();

  // Calculer la largeur en soustrayant la taille du menu
  //const contentWidth = `calc(100% - 240px)`; // Remplacez 240px par la largeur réelle de votre menu

  return (
    <Box
      component="main"
      sx={{
        flexGrow: 1,
        p: 5,
        backgroundColor: darkMode? themes.dark.backgroundColor : themes.light.backgroundColor,
        color: darkMode? themes.dark.text : themes.light.textColor,
        minHeight:'100vh'
      }}
    >
      {/* <Box sx={{ margin: '2%'}}> */}
        <Box sx={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center'}}>
          <Typography  textColor={darkMode? themes.dark.text : themes.light.textColor} style={{ fontSize: '2.5rem', marginBottom: '1%'}}>{t('PROJETS')}</Typography><br></br>
        <MediaCard></MediaCard>
        </Box>
        {/* </Box> */}
    </Box>
  );
};

export default MesProjets;
