import React from 'react';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import IconButton from '@mui/material/IconButton';
import CloseIcon from '@mui/icons-material/Close';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import Card from '@mui/joy/Card';
import CardContent from '@mui/joy/CardContent';
import CardCover from '@mui/joy/CardCover';
import LocationOnRoundedIcon from '@mui/icons-material/LocationOnRounded';
import { styled } from '@mui/material/styles';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';

const BootstrapDialog = styled(Dialog)(({ theme }) => ({
  '& .MuiDialog-paper': {
    backgroundColor: 'white',
    maxWidth: '60%',
  },
  '& .MuiDialogContent-root': {
    padding: theme.spacing(2),
    display: 'flex',
    flexWrap: 'wrap',
    justifyContent: 'center',
  },
  '& .MuiDialogActions-root': {
    padding: theme.spacing(1),
  },
}));

const ExperienceDialog = ({ open, onClose, title, location, image, descriptions }) => {
  const { darkMode } = useThemeContext();

  return (
    <BootstrapDialog
      onClose={onClose}
      aria-labelledby="customized-dialog-title"
      open={open}
    >
      <DialogTitle
        sx={{
          textAlign: 'center',
          m: 0,
          p: 2,
          bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
          color: darkMode ? themes.dark.text : themes.light.textColor,
          fontSize: '2.5rem'
        }}
        id="customized-dialog-title"
      >
        {title}
      </DialogTitle>
      <IconButton
        aria-label="close"
        onClick={onClose}
        sx={{
          position: 'absolute',
          right: 8,
          top: 8,
          color: (theme) => theme.palette.grey[500],
        }}
      >
        <CloseIcon />
      </IconButton>
      <DialogContent
        dividers
        sx={{
          bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
          display: 'flex',
          flexDirection: { xs: 'column', md: 'row' },
          gap: 4
        }}
      >
        <Card
          sx={{
            width: '100%',
            maxWidth: 500,
            minHeight: 300,
            margin: '0 auto 20px',
            boxShadow: 'none',
            '@media (min-width:1665px)': {
              width: '45%',
            }
          }}
        >
          <CardCover>
            <img
              src={image}
              alt={title}
              loading="lazy"
              style={{ objectFit: 'cover' }}
            />
          </CardCover>
          <CardCover
            sx={{
              background:
                'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 100px), linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0) 200px)',
            }}
          />
          <CardContent sx={{ justifyContent: 'flex-end', p: 2 }}>
            <Typography level="title-lg" textColor="#fff" mb={1} sx={{ textShadow: '0 2px 4px rgba(0,0,0,0.5)' }}>
              {title}
            </Typography>
            <Typography
              startDecorator={<LocationOnRoundedIcon sx={{ fontSize: '16px' }} />}
              textColor="neutral.300"
              fontSize="sm"
            >
              {location}
            </Typography>
          </CardContent>
        </Card>
        <Box
          sx={{
            width: '100%',
            maxWidth: 800,
            marginTop: { xs: 2, lg: 0 },
            '@media (min-width:1665px)': {
              width: '45%',
            },
          }}
        >
          {descriptions.map((description, index) => (
            <React.Fragment key={index}>
              <Typography
                gutterBottom
                sx={{
                  color: darkMode ? themes.dark.text : themes.light.textColor,
                  marginTop: index === 0 ? '2%' : 0,
                  marginBottom: index === descriptions.length - 1 ? '2%' : 0
                }}
              >
                {description}
              </Typography>
              {index < descriptions.length - 1 && <br />}
            </React.Fragment>
          ))}
        </Box>
      </DialogContent>
    </BootstrapDialog>
  );
};

export default ExperienceDialog;