import React from 'react';
import Card from '@mui/joy/Card';
import CardContent from '@mui/joy/CardContent';
import CardOverflow from '@mui/joy/CardOverflow';
import AspectRatio from '@mui/joy/AspectRatio';
import Divider from '@mui/joy/Divider';
import Typography from '@mui/joy/Typography';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';

const ExperienceCard = ({ image, title, content, period, onClick }) => {
  const { darkMode } = useThemeContext();

  return (
    <Card
      variant="outlined"
      onClick={onClick}
      sx={{
        width: 350,
        margin: '20px',
        borderRadius: 3,
        transition: '0.2s',
        '&:hover': { transform: 'scale(1.05)' },
        bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
        cursor: 'pointer'
      }}
    >
      <CardOverflow>
        <AspectRatio ratio="2">
          <img
            src={image}
            alt={title}
            style={{ width: '100%', height: '100%', objectFit: 'cover' }}
          />
        </AspectRatio>
      </CardOverflow>
      <CardContent>
        <Typography level="title-lg" sx={{ color: darkMode ? themes.dark.text : themes.light.textColor }}>
          {title}
        </Typography>
        <br />
        <Typography level="title-md" sx={{ color: darkMode ? themes.dark.text : themes.light.textColor }}>
          {content}
        </Typography>
        <br />
        <Divider inset="context" />
        <Typography level="body-sm" sx={{ color: darkMode ? themes.dark.primaryColor : themes.light.primaryColor }}>
          {period}
        </Typography>
      </CardContent>
    </Card>
  );
};

export default ExperienceCard;