import ImageList from '@mui/material/ImageList';
import ImageListItem from '@mui/material/ImageListItem';
import Box from '@mui/material/Box';
import vache from './../../img/vache.png';
import cepe from './../../img/cepe.jpg';
import llanes from './../../img/llanes.jpg';
import neige from './../../img/niege.png';
import remisediplome from './../../img/remisediplome.jpg';
import fumee from './../../img/fumee.jpeg';
import tennis from './../../img/tennis.jpeg';
import padel from './../../img/padel.JPG';
import musee from './../../img/musee.jpeg';
import lac from './../../img/lac.jpeg';
import { useTranslation } from 'react-i18next'; 


function srcset(image, size, rows = 1, cols = 1) {
  return {
    src: `${image}?w=${size * cols}&h=${size * rows}&fit=crop&auto=format`,
    srcSet: `${image}?w=${size * cols}&h=${
      size * rows
    }&fit=crop&auto=format&dpr=2 2x`,
  };
}

export default function About() {
    const { t } = useTranslation();

  return (
    <Box sx={{
      padding: '4%',
      margin:'3%',
    }}>
    <Box sx={{
      display: 'flex', 
      flexDirection: { xs: 'column', md: 'row' }, // Colonne sur mobile, ligne sur desktop
      justifyContent: 'space-between', // Centre le bloc complet
      alignItems: 'center', 
      gap: 4, // Espace entre le texte et les images
      boxSizing: 'border-box' 
    }}>
      {/* Conteneur Texte */}
      <Box sx={{ width: { xs: '100%', md: '37%' }, textAlign: 'left' }}>
        <h2 style={{ fontSize: '2.6rem', fontFamily: '"Comfortaa", sans-serif' }}>À PROPOS DE MOI</h2>
        <p> {t('ABOUTME')}</p>
        <a 
            href="https://checker-streetcar-11d.notion.site/Livres-276e895374f980e495cecbf600c42fad" 
            target="_blank" 
            rel="noopener noreferrer"
            style={{ color: '#1976d2', textDecoration: 'underline' }}
            >
            ici
            </a>. <p> {t('ABOUTME2')}</p>
      </Box>

      {/* Conteneur Galerie */}
      <ImageList
        sx={{
            width: { xs: '100%', md: '60%' },
            overflow: 'hidden',
            // On cible les images à l'intérieur pour l'animation
            '& .MuiImageListItem-root': {
            overflow: 'hidden',
            borderRadius: '8px',
            },
            '& img': {
            transition: 'transform 0.5s ease',
            },
            '& img:hover': {
            transform: 'scale(1.15)', // Intensité du zoom
            cursor: 'pointer',
            },
        }}
        variant="quilted"
        cols={4}
        rowHeight={170}
        gap={15}
        >
        {itemData.map((item) => (
            <ImageListItem key={item.img} cols={item.cols || 1} rows={item.rows || 1}>
            <img
                src={item.img}
                alt={item.title}
                loading="lazy"
                style={{ 
                width: '100%', 
                height: '100%', 
                objectFit: 'cover' 
                }}
            />
            </ImageListItem>
        ))}
        </ImageList>
      </Box>
    </Box>
  );
}

const itemData = [
  // --- PARTIE HAUTE (Le contenu dans le creux du L) ---
  {
    img: vache,
    title: 'Vache',
    rows: 1,
    cols: 2,
  },
  {
    img: neige,
    title: 'Neige',
    rows: 1,
    cols: 1,
  },
  // --- LA BARRE VERTICALE DU L (À droite) ---
  {
    img: llanes,
    title: 'Padel',
    rows: 3, // Très haute
    cols: 1, // Sur la dernière colonne
  },
  // --- LA BARRE HORIZONTALE DU L (En bas) ---
  {
    img: fumee,
    title: 'Llanes',
    rows: 1,
    cols: 2, // S'étend sous les autres images
  },
  {
    img: remisediplome,
    title: 'Llanes',
    rows: 2,
    cols: 1, // S'étend sous les autres images
  },
  // --- LE RESTE POUR COMBLER ---
  {
    img: cepe,
    rows: 1,
    cols: 1,
  },
  {
    img: lac,
    rows: 1,
    cols: 1,
  },
];