import React from 'react';
import { Box, Accordion, AccordionSummary, AccordionDetails } from '@mui/material';
import Typography from '@mui/joy/Typography';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import SchoolCard from './formationCard';
import { useThemeContext } from './../Burger/themeContext';
import themes from './../Burger/theme'

const TimelineItem = ({ title, subtitle, dates, description, image, locationName, isScreenWide, t }) => {
  const { darkMode } = useThemeContext();
  const primaryColor = darkMode ? themes.dark.primaryColor : themes.light.primaryColor;
  const textColor = darkMode ? themes.dark.text : themes.light.textColor;

  return (
    <Box sx={{ position: 'relative' }}>
      {/* Le point sur la ligne */}
      <Box sx={{
        position: 'absolute',
        left: { xs: '-20px', sm: '-34px' },
        top: '50%',
        transform: 'translateY(-50%)',
        width: '10px',
        height: '10px',
        borderRadius: '50%',
        backgroundColor: darkMode ? themes.dark.primaryColor : themes.light.primaryColor,
        zIndex: 3,
      }} />

      <Accordion sx={{ 
        width: isScreenWide ? '98%' : '85%', 
        margin: '5px',
        backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
        color: 'white'
      }}>
        <AccordionSummary
          expandIcon={<ExpandMoreIcon style={{ color: primaryColor }} />}
        >
          <Box sx={{ display: 'flex', flexDirection: 'column', width: '100%' }}>
            <Typography textColor={primaryColor} style={{ fontSize: '2rem', textAlign: 'left' }}>{title}</Typography>
            <Typography textColor={textColor} style={{ fontSize: '1rem', textAlign: 'left' }}>{subtitle}</Typography>
            {!isScreenWide && (
              <Typography textColor={primaryColor} style={{ fontSize: '1.3rem', textAlign: 'left' }}>{dates}</Typography>
            )}
          </Box>
          {isScreenWide && (
            <Box sx={{ width: '200px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Typography textColor={primaryColor} style={{ fontSize: '1.6rem', textAlign: 'left' }}>{dates}</Typography>
            </Box>
          )}
        </AccordionSummary>
        <AccordionDetails>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', gap: '20px' }}>
            <Box sx={{ width: { xs: '100%', sm: '55%' } }}>
              <Typography textColor={textColor} style={{ fontSize: '1rem', textAlign: 'left' }}>
                {description}
              </Typography>
            </Box>
            <SchoolCard image={image} locationName={locationName} isScreenWide={isScreenWide} />
          </Box>
        </AccordionDetails>
      </Accordion>
    </Box>
  );
};

export default TimelineItem;