import React from 'react';
import { Box, Typography, Divider, Paper, Stack } from '@mui/material';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';
import cleanCodeCover from '../../img/cleancode.jpg';
import DDD from '../../img/DDD.jpg';
import guidedbytests from '../../img/guidedbytests.jpg';

const books = [
  {
    title: "Clean Code",
    author: "Robert C. Martin",
    cover: cleanCodeCover,
    summary: "Ce que j'ai retenu :",
    notes: "L'importance de la règle du boy-scout : toujours laisser le code plus propre qu'on ne l'a trouvé. La clarté prime sur l'astuce technique.",
    color: "#e67e22"
  },
  {
    title: "Domain Driven Design",
    author: "Eric Evans",
    cover: DDD,
    summary: "Ce que j'ai retenu :",
    notes: "Une vision fascinante sur la capacité des humains à coopérer grâce à des mythes communs. Ça aide à comprendre la culture d'entreprise !",
    color: "#27ae60"
  },
  {
    title: "Growing Object-Oriented Software, Guided by Tests",
    author: "Steve Freeman & Nat Pryce",
    cover: guidedbytests,
    summary: "Prochaine lecture",
    notes: " ",
    color: "#2980b9"
  }
];

function Reads() {
  const { darkMode } = useThemeContext();
  
  // Raccourcis pour la lisibilité
  const currentTheme = darkMode ? themes.dark : themes.light;

  return (
    <Box sx={{
      height: '100vh',
      overflowY: 'auto',
      backgroundColor: currentTheme.backgroundColor,
      p: 4,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      scrollbarWidth: 'none',
      '&::-webkit-scrollbar': { display: 'none' },
    }}>
      <Typography variant="h2" sx={{ 
        mb: 10, 
        textAlign: 'center', 
        color: darkMode ? currentTheme.textTitle : currentTheme.textColor,
        fontFamily: '"Comfortaa", sans-serif',
        fontSize: '2.6rem',
        fontWeight: 'bold'
      }}>
        Mes lectures
      </Typography>

      <Stack spacing={12} sx={{ width: '100%', maxWidth: '1100px', alignItems: 'center' }}>
        {books.map((book, index) => {
          const isEven = index % 2 !== 0;
          return (
            <Box 
              key={index} 
              sx={{ 
                display: 'flex', 
                width: '100%',
                justifyContent: isEven ? 'flex-end' : 'flex-start',
              }}
            >
              <Box 
                sx={{ 
                  display: 'flex', 
                  flexDirection: { xs: 'column', md: isEven ? 'row-reverse' : 'row' },
                  alignItems: 'flex-start', // Aligne le haut de l'image avec le haut du texte
                  gap: 6,
                  width: { xs: '100%', md: '90%' },
                  maxWidth: '900px'
                }}
              >
                {/* Couverture du livre */}
                <Box sx={{ flexShrink: 0 }}>
                  <Paper 
                    elevation={12} 
                    sx={{ 
                      width: '220px', 
                      height: '320px', 
                      backgroundImage: `url(${book.cover})`,
                      backgroundSize: 'cover',
                      backgroundPosition: 'center',
                      // Effet reliure dynamique selon le côté
                      borderRadius: isEven ? '15px 4px 4px 15px' : '4px 15px 15px 4px', 
                      borderLeft: isEven ? 'none' : `6px solid ${book.color}`,
                      borderRight: isEven ? `6px solid ${book.color}` : 'none',
                    }} 
                  />
                </Box>

                {/* Analyse et description */}
                <Box sx={{ flex: 1, textAlign: 'left', pt: 1 }}>
                  <Typography variant="h4" sx={{ 
                    fontFamily: '"Comfortaa", sans-serif',
                    color: currentTheme.text,
                    lineHeight: 1.2,
                    mb: 1
                  }}>
                    {book.title}
                  </Typography>
                  
                  <Typography variant="subtitle1" sx={{ 
                    mb: 3, 
                    fontStyle: 'italic', 
                    opacity: 0.8, 
                    color: currentTheme.text 
                  }}>
                    par {book.author}
                  </Typography>
                  
                  <Divider sx={{ mb: 3, width: '60px', borderBottomWidth: 4, borderColor: book.color }} />
                  
                  <Typography variant="h6" gutterBottom sx={{ color: currentTheme.text, fontWeight: 'bold' }}>
                    {book.summary}
                  </Typography>
                  
                  <Typography variant="body1" sx={{ 
                    lineHeight: 1.8, 
                    opacity: 0.9, 
                    color: currentTheme.text,
                    fontSize: '1.1rem'
                  }}>
                    {book.notes}
                  </Typography>
                </Box>
              </Box>
            </Box>
          );
        })}
      </Stack>
    </Box>
  );
}

export default Reads;