import React from 'react';
import { Card, CardCover, CardContent, Typography } from '@mui/joy';
import LocationOnRoundedIcon from '@mui/icons-material/LocationOnRounded';
import { useThemeContext } from './../Burger/themeContext';
import themes from './../Burger/theme'

function FormationCard({ image, locationName, isScreenWide }) {
  const { darkMode } = useThemeContext();

  return (
    <Card sx={{ 
    height: isScreenWide ? '200px' : '120px', 
    width: isScreenWide ? '330px' : '100%', 
    border: 'none' 
  }}>
    <CardCover>
      <img src={image} loading="lazy" alt={locationName} />
    </CardCover>
    <CardCover sx={{ borderRadius: 2 }} />
    <CardContent sx={{ justifyContent: 'flex-end' }}>
      <Typography startDecorator={<LocationOnRoundedIcon />} textColor="neutral.300">
        {locationName}
      </Typography>
    </CardContent>
  </Card>
  );
}

export default FormationCard;