import Box from '@mui/material/Box';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';
import Bienvenue from './bienvenue';
import About from './about';
import Competences from './competences';
import { useRef } from 'react';
import ScrollIndicator from './scrollIndicator';

function Home() {
  const { darkMode } = useThemeContext();
  
  const welcomeRef = useRef(null);
  const aboutRef = useRef(null);
  const skillsRef = useRef(null);

  const scrollToSection = (ref) => {
    ref.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const containerStyle = {
    height: '100vh',
    overflowY: 'scroll',
    scrollSnapType: 'y mandatory', // Active le magnétisme vertical
    scrollBehavior: 'smooth',
    backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
    color: darkMode ? themes.dark.text : themes.light.textColor,
    '&::-webkit-scrollbar': { display: 'none' }, // Optionnel: cache la scrollbar
    msOverflowStyle: 'none', 
    scrollbarWidth: 'none',
  };

  const sectionStyle = {
  height: '100vh',
  scrollSnapAlign: 'start',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  overflow: 'hidden', // Sécurité anti-débordement
  position: 'relative',
};

  return (
    <Box component="main" sx={containerStyle}>
      <Box sx={sectionStyle} ref={welcomeRef}>
        <Bienvenue onNext={() => scrollToSection(aboutRef)} />
        <ScrollIndicator onClick={() => scrollToSection(aboutRef)} />
      </Box>

      <Box sx={sectionStyle} ref={aboutRef}>
        <About onNext={() => scrollToSection(skillsRef)} />
        <ScrollIndicator onClick={() => scrollToSection(skillsRef)} />
      </Box>

      <Box sx={sectionStyle} ref={skillsRef}>
        <Competences />
      </Box>
    </Box>
  );
}

export default Home;