import React from 'react';
import { Box, useMediaQuery } from '@mui/material';
import Typography from '@mui/joy/Typography';
import { useTranslation } from 'react-i18next';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';
import TimelineItem from './timelineItem';

// Imports images
import civ from '../../img/civ.jpg';
import efrei from '../../img/efreicampus-8334.jpg';
import unica from '../../img/iut.jpg';
import lucioles from '../../img/lucioles.jpg';

function Formation() {
  const { t } = useTranslation();
  const { darkMode } = useThemeContext();
  const isScreenWide = useMediaQuery('(min-width:600px)');

  const commonProps = { themes, darkMode, isScreenWide, t };

  return (
    <Box component="main" sx={{
      flexGrow: 1, p: 3,
      backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
      color: darkMode ? themes.dark.text : themes.light.textColor,
      minHeight: '100vh'
    }}>
      <Box sx={{ 
        margin: '2%', padding: '2%', borderRadius: '10px',
        bgcolor: darkMode ? themes.dark.encadre : themes.light.encadre,
      }}>
        <Typography textColor={darkMode ? themes.dark.text : themes.light.textColor} sx={{ fontSize: '2.5rem', textAlign: 'center' }}>
          {t('FORMATION')}
        </Typography>

        <Box sx={{ position: 'relative', paddingLeft: { xs: '30px', sm: '50px' }, marginTop: '4%' }}>
          {/* Ligne verticale */}
          <Box sx={{
            position: 'absolute', left: { xs: '10px', sm: '20px' },
            top: 0, bottom: 0, width: '3px', backgroundColor: darkMode ? themes.dark.darker : themes.light.darkerdarker,
          }} />

          <Box sx={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            <TimelineItem 
              {...commonProps}
              title={t('UNIVERSITE')} subtitle={t('MASTER')} dates="2025 - 2026"
              description={t('DESCIUT')} image={lucioles} locationName="Université Côte d'Azur campus des lucioles"
            />
            <TimelineItem 
              {...commonProps}
              title={t('IUT')} subtitle={t('DUT')} dates="2023 - 2025"
              description={t('DESCIUT')} image={unica} locationName="Institut Universitaire Technologique"
            />
            <TimelineItem 
              {...commonProps}
              title="Efrei" subtitle={t('EFREEIDIPLOME')} dates="2022 - 2023"
              description={<>{t('EFREIDESC1')}<br/>{t('EFREIDESC2')}</>} image={efrei} locationName="EFREI - Grande École du Numérique"
            />
            <TimelineItem 
              {...commonProps}
              title={t('LIV')} subtitle={t('BAC')} dates="2019 - 2022"
              description={t('LIVDESC')} image={civ} locationName="Centre International de Valbonne"
            />
          </Box>
        </Box>
      </Box>
    </Box>
  );
}

export default Formation;