import React, { useState } from 'react';
import Box from '@mui/material/Box';
import Typography from '@mui/joy/Typography';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';
import { useTranslation } from 'react-i18next';
import STMicroelectronics from './../../img/ST.png';
import Harvest from './../../img/Harvest.JPG';
import harvestdecor from './../../img/harvestdecor.jpg';
import STdecor from './../../img/STdecor.jpg';
import ExperienceCard from './experienceCard';
import ExperienceDialog from './experienceDialog';
import Amadeus from './../../img/Amadeus.png';

function Experiences() {
  const { darkMode } = useThemeContext();
  const { t } = useTranslation();
  const [openST, setOpenST] = useState(false);
  const [openHarvest, setOpenHarvest] = useState(false);

  const experiences = [
    {
      id: 'amadeus',
      image: Amadeus,
      title: t('AMADEUSCARDTITLE'),
      content: t('AMADEUSCARDCONTENT'),
      period: '01/09/2025 - now',
      onClick: () => setOpenST(true),
      dialogProps: {
        title: 'Amadeus',
        location: 'Sophia Antipolis, France',
        image: STdecor,
        descriptions: [
          t('ABOUT_AMADEUS_DESCRIPTION_1'),
          t('ABOUT_AMADEUS_DESCRIPTION_2'),
          t('ABOUT_AMADEUS_DESCRIPTION_3'),
        ]
      }
    },
    {
      id: 'st',
      image: STMicroelectronics,
      title: t('STCARDTITLE'),
      content: t('STCARDCONTENT'),
      period: '01/09/2023 - 01/09/2025',
      onClick: () => setOpenST(true),
      dialogProps: {
        title: 'STMicroelectronics',
        location: 'Sophia Antipolis, France',
        image: STdecor,
        descriptions: [
          t('ABOUT_ST_DESCRIPTION_1'),
          t('ABOUT_ST_DESCRIPTION_2'),
          t('ABOUT_ST_DESCRIPTION_3'),
        ]
      }
    },
    {
      id: 'harvest',
      image: Harvest,
      title: t('HARVESTCARDTITLE'),
      content: t('HARVESTCARDCONTENT'),
      period: '07/05/2023 - 07/07/2023',
      onClick: () => setOpenHarvest(true),
      dialogProps: {
        title: 'Harvest',
        location: 'Sophia Antipolis, France',
        image: harvestdecor,
        descriptions: [
          t('ABOUT_HARVEST_DESCRIPTION_1'),
          t('ABOUT_HARVEST_DESCRIPTION_2'),
          t('ABOUT_HARVEST_DESCRIPTION_3'),
        ]
      }
    }
  ];

  return (
    <Box
      component="main"
      sx={{
        flexGrow: 1,
        p: 5,
        minHeight: '100vh',
        backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
      }}
    >
      <Box sx={{ textAlign: 'center' }}>
        <Typography
          textColor={darkMode ? themes.dark.text : themes.light.textColor}
          style={{ fontSize: '2.5rem', marginBottom: '3%' }}
        >
          {t('EXPERIENCE')}
        </Typography>
        <br />

        <Box style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'space-evenly', textAlign: 'left' }}>
          {experiences.map((experience) => (
            <ExperienceCard
              key={experience.id}
              image={experience.image}
              title={experience.title}
              content={experience.content}
              period={experience.period}
              onClick={experience.onClick}
            />
          ))}
        </Box>
      </Box>

      <ExperienceDialog
        open={openST}
        onClose={() => setOpenST(false)}
        {...experiences[0].dialogProps}
      />

      <ExperienceDialog
        open={openHarvest}
        onClose={() => setOpenHarvest(false)}
        {...experiences[1].dialogProps}
      />
    </Box>
  );
}

export default Experiences;