import * as React from 'react';
import PropTypes from 'prop-types';
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import CssBaseline from '@mui/material/CssBaseline';
import Drawer from '@mui/material/Drawer';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import Typography from '@mui/material/Typography';
import { grey } from '@mui/material/colors';
import ContactMailIcon from '@mui/icons-material/ContactMail';
import CodeIcon from '@mui/icons-material/Code';
import DesktopWindowsSharpIcon from '@mui/icons-material/DesktopWindowsSharp';
import { Link } from 'react-router-dom';
import './drawer.css';
import SelectLang from './selectLang';
import { useTranslation } from 'react-i18next';
import SchoolIcon from '@mui/icons-material/School';
import HomeIcon from '@mui/icons-material/Home';
import SwitchBut from './mode';
import IconButton from '@mui/material/IconButton';
import AccountCircleIcon from '@mui/icons-material/AccountCircle';
import Avatar from './avatar';
import MenuIcon from '@mui/icons-material/Menu';
import Stack from '@mui/material/Stack';
import { useThemeContext } from './themeContext';
import { useLocation } from 'react-router-dom';
import themes from './theme';
import Divider from '@mui/material/Divider';
import ExpandLess from '@mui/icons-material/ExpandLess';
import ExpandMore from '@mui/icons-material/ExpandMore';
import Collapse from '@mui/material/Collapse';
import MenuBookIcon from '@mui/icons-material/MenuBook';
import AssignmentIcon from '@mui/icons-material/Assignment';
import ExtensionIcon from '@mui/icons-material/Extension';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';

const drawerWidth = 260;

function ResponsiveDrawer(props) {
  const { t } = useTranslation();
  const { window } = props;
  const [mobileOpen, setMobileOpen] = React.useState(false);
  const [isClosing, setIsClosing] = React.useState(false);
  const [anchorEl, setAnchorEl] = React.useState(null);
  const {darkMode} = useThemeContext();
  const location = useLocation();

  const handleProjetsClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleProjetsClose = () => {
    setAnchorEl(null);
  };

  const handleDrawerClose = () => {
    setIsClosing(true);
    setMobileOpen(false);
  };

  const handleDrawerTransitionEnd = () => {
    setIsClosing(false);
  };

  const handleDrawerToggle = () => {
    if (!isClosing) {
      setMobileOpen(!mobileOpen);
    }
  };

const navItemStyle = (active, darkMode) => ({
  position: 'relative',
  borderRadius: '12px',
  marginX: '12px',
  marginY: '6px',
  paddingY: '10px',
  paddingX: '16px',

  transition: 'all 220ms cubic-bezier(0.4, 0, 0.2, 1)',

  backgroundColor: active
    ? 'rgba(111,163,154,0.18)'
    : 'transparent',

  color: active
    ? themes.dark.primaryColor
    : darkMode
      ? themes.dark.text
      : themes.light.textColor,

  transform: active ? 'scale(1.02)' : 'scale(1)',

  boxShadow: active
    ? '0 4px 14px rgba(0,0,0,0.25)'
    : 'none',

  '&:hover': {
    transform: 'scale(1.05) translateY(-2px)',
    backgroundColor: active
      ? 'rgba(111,163,154,0.28)'
      : 'rgba(111,163,154,0.12)',
    boxShadow: '0 8px 22px rgba(0,0,0,0.35)',
  },
});

const menuItemStyle = (darkMode) => ({
  paddingY: '10px',
  paddingX: '20px',
  minWidth: '200px',
  color: darkMode ? themes.dark.text : themes.light.textColor,
  '&:hover': {
    backgroundColor: 'rgba(111,163,154,0.12)',
  },
});


  const drawer = (
    <div sx={{ display: 'flex', flexDirection: 'column'}} className="drawer-container">
      <List
        sx={{
          display: 'flex',
          justifyContent: 'space-around'
        }}
      >
        <SwitchBut />
        <SelectLang />
      </List>
      <List
      sx={{
        color : darkMode? themes.dark.text : themes.light.textColor,
      }}>
        <Stack sx={{marginTop: '10%'}}>
        {/* <Avatar /> */}
        </Stack>
        <Typography variant="h4" gutterBottom sx={{textAlign: 'left', marginLeft: '20px', marginTop: '10%', marginBottom:'15px', fontFamily: '"Comfortaa", sans-serif'}}> 
        Louise Sanchez
      </Typography>
      <Divider sx={{ borderColor: darkMode ? themes.dark.darker : themes.light.primaryColor, marginBottom: '15px', width: '80%', margin: '0 auto' }}/>
      <Box sx={{display: 'flex', flexDirection: 'column', gap:'3px', marginBottom:'10px', marginTop:'10px'
      }}>
        <Typography sx={{textAlign: 'left', marginLeft: '20px', color : darkMode? themes.dark.primaryColor : themes.light.textColor, fontSize: '0.9rem'}}>
        07 81 86 72 90
        </Typography>
        <Typography sx={{textAlign: 'left', marginLeft: '20px', color : darkMode? themes.dark.primaryColor : themes.light.textColor, fontSize: '0.9rem'}}>
          louise.sanchez62@gmail.com
        </Typography>
        <Typography sx={{textAlign: 'left', marginLeft: '20px', color : darkMode? themes.dark.primaryColor : themes.light.textColor, fontSize: '0.9rem'}}>
          Valbonne, Sophia Antipolis
        </Typography>
      </Box>
      <Divider sx={{ borderColor: darkMode ? themes.dark.darker : themes.light.primaryColor, marginBottom: '15px', width: '80%', margin: '0 auto' }}/>
      </List>
      <List sx={{ color : darkMode? themes.dark.text : themes.light.textColor, maxHeight: '60%', height: '60%', marginTop: '10%',display: 'flex',
        justifyContent: 'space-between', flexDirection: 'column'}}>
        <Stack>
        {/* Accueil */}
        <ListItem key={t('ACCUEIL')} disablePadding>
          <ListItemButton component={Link} to={'/'} onClick={handleDrawerToggle} sx={navItemStyle(location.pathname === '/', darkMode)}>
          <ListItemIcon sx={{ minWidth: 40, color: location.pathname === '/' ? (darkMode ? themes.dark.primaryColor : themes.light.primaryColor) : grey[500] }}>
            <HomeIcon sx={{'&:hover': { color: darkMode ?themes.dark.primaryColor : themes.light.primaryColor} }} />
          </ListItemIcon>
          <ListItemText >
            <Typography variant="body1"  sx={{ 
              fontFamily: "'Lexend Giga', sans-serif",
            }}>
              {t('ACCUEIL')}
            </Typography>
          </ListItemText>
          </ListItemButton>
        </ListItem>

        {/* Section Projets avec menu popup */}
        <ListItem key={t('PROJETS')} disablePadding>
          <ListItemButton onClick={handleProjetsClick} sx={navItemStyle(['/lectures', '/projets-scolaires', '/extracurricular'].includes(location.pathname), darkMode)}>
            <ListItemIcon sx={{ minWidth: 40, color: ['/lectures', '/projets-scolaires', '/extracurricular'].includes(location.pathname) ? (darkMode ? themes.dark.primaryColor : themes.light.primaryColor) : grey[500] }}>
              <CodeIcon sx={{'&:hover': { color: darkMode ?themes.dark.primaryColor : themes.light.primaryColor} }} />
            </ListItemIcon>
            <ListItemText>
              <Typography variant="body1" sx={{ 
                fontFamily: "'Lexend Giga', sans-serif",
              }}>
                {t('PROJETS')}
              </Typography>
            </ListItemText>
            <ExpandMore />
          </ListItemButton>
        </ListItem>

        {/* Menu popup pour les sous-catégories */}
        <Menu
          anchorEl={anchorEl}
          open={Boolean(anchorEl)}
          onClose={handleProjetsClose}
          anchorOrigin={{
            vertical: 'bottom',
            horizontal: 'left',
          }}
          transformOrigin={{
            vertical: 'top',
            horizontal: 'left',
          }}
          PaperProps={{
            sx: {
              backgroundColor: darkMode ? themes.dark.surface : themes.light.surface,
              borderRadius: '12px',
              boxShadow: '0 8px 24px rgba(0,0,0,0.25)',
              border: `1px solid ${darkMode ? themes.dark.darker : themes.light.primaryColor}`,
              marginTop: '8px',
              marginLeft: '12px',
              width: '220px',
            }
          }}
        >
          <MenuItem 
            component={Link} 
            to={'/reads'} 
            onClick={() => { handleProjetsClose(); handleDrawerToggle(); }}
            sx={menuItemStyle(darkMode)}
          >
            <ListItemIcon sx={{ minWidth: 40, color: darkMode ? themes.dark.primaryColor : themes.light.primaryColor }}>
              <MenuBookIcon fontSize="small" />
            </ListItemIcon>
            <Typography variant="body2" sx={{ fontFamily: "'Lexend Giga', sans-serif" }}>
              Mes Lectures
            </Typography>
          </MenuItem>

          <MenuItem 
            component={Link} 
            to={'/projets-scolaires'} 
            onClick={() => { handleProjetsClose(); handleDrawerToggle(); }}
            sx={menuItemStyle(darkMode)}
          >
            <ListItemIcon sx={{ minWidth: 40, color: darkMode ? themes.dark.primaryColor : themes.light.primaryColor }}>
              <AssignmentIcon fontSize="small" />
            </ListItemIcon>
            <Typography variant="body2" sx={{ fontFamily: "'Lexend Giga', sans-serif" }}>
              Projets Scolaires
            </Typography>
          </MenuItem>

          <MenuItem 
            component={Link} 
            to={'/extracurricular'} 
            onClick={() => { handleProjetsClose(); handleDrawerToggle(); }}
            sx={menuItemStyle(darkMode)}
          >
            <ListItemIcon sx={{ minWidth: 40, color: darkMode ? themes.dark.primaryColor : themes.light.primaryColor }}>
              <ExtensionIcon fontSize="small" />
            </ListItemIcon>
            <Typography variant="body2" sx={{ fontFamily: "'Lexend Giga', sans-serif" }}>
              Extrascolaire
            </Typography>
          </MenuItem>
        </Menu>

        {/* Formation */}
        <ListItem key={t('FORMATION')} disablePadding>
          <ListItemButton component={Link} to={'/formation'} onClick={handleDrawerToggle} sx={navItemStyle(location.pathname === '/formation', darkMode)}>
          <ListItemIcon sx={{ minWidth: 40, color: location.pathname === '/formation' ? (darkMode ? themes.dark.primaryColor : themes.light.primaryColor) : grey[500] }}>
            <SchoolIcon sx={{'&:hover': { color: darkMode ?themes.dark.primaryColor : themes.light.primaryColor} }} />
          </ListItemIcon>
          <ListItemText >
            <Typography variant="body1"  sx={{ 
              fontFamily: "'Lexend Giga', sans-serif",
            }}>
              {t('FORMATION')}
            </Typography>
          </ListItemText>
          </ListItemButton>
        </ListItem>

        {/* Experience */}
        <ListItem key={t('EXPERIENCE')} disablePadding>
          <ListItemButton component={Link} to={'/experiences'} onClick={handleDrawerToggle} sx={navItemStyle(location.pathname === '/experiences', darkMode)}>
          <ListItemIcon sx={{ minWidth: 40, color: location.pathname === '/experiences' ? (darkMode ? themes.dark.primaryColor : themes.light.primaryColor) : grey[500] }}>
            <DesktopWindowsSharpIcon sx={{'&:hover': { color: darkMode ?themes.dark.primaryColor : themes.light.primaryColor} }} />
          </ListItemIcon>
          <ListItemText >
            <Typography variant="body1"  sx={{ 
              fontFamily: "'Lexend Giga', sans-serif",
            }}>
              {t('EXPERIENCE')}
            </Typography>
          </ListItemText>
          </ListItemButton>
        </ListItem>
      </Stack>
      <Stack>
          <ListItem key={t('CONTACT')} disablePadding>
            <ListItemButton component={Link} to={'/contact'} onClick={handleDrawerToggle} sx={navItemStyle(location.pathname === '/contact', darkMode)}>
            <ListItemIcon sx={{ minWidth: 40, color: location.pathname === '/contact' ? (darkMode ? themes.dark.primaryColor : themes.light.primaryColor) : grey[500] }}>{<ContactMailIcon />}</ListItemIcon>
            <ListItemText >
              <Typography variant="body1"  sx={{ 
                fontFamily: "'Lexend Giga', sans-serif",
              }}>
                {t('CONTACT')}
              </Typography>
            </ListItemText>
            </ListItemButton>
        </ListItem>
        </Stack>
      </List>
    </div>
  );

  const container = window !== undefined ? () => window().document.body : undefined;

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', background: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor}} className="drawer-container">
      <CssBaseline />
      <Box sx={{ display: 'flex', justifyContent: 'flex-start', alignItems: 'flex-start'}}>
          <IconButton
            aria-label="open drawer"
            edge="start"
            onClick={handleDrawerToggle}
            sx={{ mr: 2, display: { sm: 'none' }, ml:'10px', color: darkMode? themes.dark.text : themes.light.textColor }}
          >
            <MenuIcon />
          </IconButton>
        </Box>
      <Box 
        component="nav"
        sx={{
            width: { sm: drawerWidth },
            flexShrink: { sm: 0 },
            overflowX: 'hidden',
          }}
        aria-label="mailbox folders"
      >
        <Drawer
          container={container}
          variant="temporary"
          open={mobileOpen}
          onTransitionEnd={handleDrawerTransitionEnd}
          onClose={handleDrawerClose}
          ModalProps={{
            keepMounted: true,
            disableScrollLock: true 
          }}
          sx={{
            display: { xs: 'block', sm: 'none' },
            '& .MuiDrawer-paper': { 
              boxSizing: 'border-box', 
              width: drawerWidth, 
              backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
              overflowX: 'hidden',
            },
          }}
        >
          {drawer}
        </Drawer>
        <Drawer
          variant="permanent"
          sx={{
            display: { xs: 'none', sm: 'block' },
            '& .MuiDrawer-paper': { 
              boxSizing: 'border-box', 
              width: drawerWidth, 
              backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
              overflowX: 'hidden',
              borderRight: `1px solid ${
              darkMode ? themes.dark.darker : themes.light.primaryColor
            }`,
            },
          }}
          open
        >
          {drawer}
        </Drawer>
      </Box>
    </Box>
  );
}

ResponsiveDrawer.propTypes = {
  window: PropTypes.func,
};

export default ResponsiveDrawer;