import DialogContent from '@mui/material/DialogContent';
import Typography from '@mui/material/Typography';
import themes from './../../Burger/theme';
import { useThemeContext } from './../../Burger/themeContext';
import spaceSquad1 from './../../../img/spacesquad1PNG.PNG';
import spaceSquad2 from './../../../img/spacesquad2PNG.PNG';
import spaceInvaders from './../../../img/spaceinvadersPNG.PNG';
import casseBrique from './../../../img/cassebriquePNG.PNG';
import Link from '@mui/material/Link';
import { useTranslation } from 'react-i18next';
import Card from '@mui/joy/Card';
import CardCover from '@mui/joy/CardCover';
import Box from '@mui/material/Box';

export function Web(){
    const {darkMode} = useThemeContext();
    const { t } = useTranslation();

    return(
        <>
        <DialogContent dividers sx={{bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor}}>
          <Box padding={4}>
          <Typography gutterBottom>
          {t('WEB_PROJECT_INTRO')}
          </Typography><br></br>
          <Card sx={{width: '65%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={spaceSquad1}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
      <CardCover
        sx={{
          background:
            'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 100px), linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0) 200px)',
        }}
      />
    </Card>
        <Link href="https://8f961501-d7a2-41e2-83bc-da12af22e791-00-14f8nepj6b2nt.janeway.replit.dev/index.html">{t('WEB_PROJECT_LINK')}</Link>
          <Typography gutterBottom>
          {t('DESCRIPTION_TITLE')}
          </Typography><br></br>
          <Typography gutterBottom>
          {t('WEB_PROJECT_DESCRIPTION_1')}
          </Typography><br></br>
          <Card sx={{width: '65%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={spaceSquad2}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
      <CardCover
        sx={{
          background:
            'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 100px), linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0) 200px)',
        }}
      />
    </Card>
      <Typography gutterBottom>
      {t('WEB_PROJECT_DESCRIPTION_2')}
      </Typography><br></br>
      <Card sx={{width: '65%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={casseBrique}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
      <CardCover
        sx={{
          background:
            'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 100px), linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0) 200px)',
        }}
      />
    </Card>
    <Card sx={{width: '65%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={spaceInvaders}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
      <CardCover
        sx={{
          background:
            'linear-gradient(to top, rgba(0,0,0,0.4), rgba(0,0,0,0) 100px), linear-gradient(to top, rgba(0,0,0,0.8), rgba(0,0,0,0) 200px)',
        }}
      />
    </Card>
    </Box>
        </DialogContent>
        </>
    )
}