import Box from '@mui/material/Box';
import React, { useRef, useState, useEffect }  from 'react';
import { useInView } from 'react-intersection-observer';
import LinearProgress from '@mui/material/LinearProgress';
import { styled } from '@mui/system';
import themes from '../Burger/theme';
import { useThemeContext } from '../Burger/themeContext';

export default function Techno() {
    const { darkMode } = useThemeContext();

    const AnimatedProgressBar = ({ value }) => {
      const [progress, setProgress] = useState(0);
      const [ref, inView] = useInView({ threshold: 0 });
    
      useEffect(() => {
        let animation = null;
        if (inView) {
          animation = setInterval(() => {
            if (progress < value) {
              setProgress(prevProgress => prevProgress + 2);
            }
          }, 20); // Adjust speed of animation if needed
        } else {
          clearInterval(animation);
        }
        return () => clearInterval(animation);
      }, [inView, progress, value]);
    
      return (
        <div ref={ref} style={{ width: '100%' }}>
          <BorderLinearProgress variant="determinate" value={progress}/>
        </div>
      );
    };

    const BorderLinearProgress = styled(LinearProgress)(({ theme }) => ({
        height: 8, 
        width: '100%', // Utiliser 100% au lieu de 400px
        maxWidth: '400px', // Limite la taille max
        margin: '10px 0',
        borderRadius: 5,
        backgroundColor: darkMode ? '#353436' : '#f1f1f1',
        '& .MuiLinearProgress-bar': {
            backgroundColor: darkMode ? themes.dark.primaryColor : themes.light.primaryColor,
        }
    }));

    return(
        <Box sx={{width: '100%'}}>
            <Box>
                <h2 style={{color: darkMode ? themes.dark.primaryColor : themes.light.primaryColor}}>BACK-END</h2> <br></br>
                <h3>Typescript / Javascript</h3>
                <AnimatedProgressBar value={80} />
                <h3>Java (Maven, Spring, Junit, Mockito)</h3>
                <AnimatedProgressBar value={60} />
                <h3>Python</h3>
                <AnimatedProgressBar value={50} />
                <h3>PHP</h3>
                <AnimatedProgressBar value={20} />
            </Box><br></br>
            <Box>
                <h2 style={{color: darkMode ? themes.dark.primaryColor : themes.light.primaryColor}}>FRONT-END</h2> <br></br>
                <h3>HTML / CSS</h3>
                <AnimatedProgressBar value={80} />
                <h3>React (Rdeux)</h3>
                <AnimatedProgressBar value={80} />
                <h3>Angular</h3>
                <AnimatedProgressBar value={35} />
            </Box>
        </Box>
    );
}