import DialogContent from '@mui/material/DialogContent';
import Typography from '@mui/material/Typography';
import themes from './../../Burger/theme';
import { useThemeContext } from './../../Burger/themeContext';
import android from './../../../img/androidstudio1.JPG';
import androidmain from './../../../img/androidmain.png';
import androidInscription from './../../../img/androidInscription.png';
import androidPagePro from './../../../img/androidPageProduit.png';
import androidPageProSnow from './../../../img/androidPageSnow.png';
import androidConf from './../../../img/androidConfirmation.png';
import androidCard from './../../../img/androidReservations.png';
import Card from '@mui/joy/Card';
import CardCover from '@mui/joy/CardCover';
import Box from '@mui/material/Box';

export function Android(){
  const {darkMode} = useThemeContext();

    return(
        <>
        <DialogContent dividers sx={{bgcolor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor, color: darkMode ? themes.dark.text : themes.light.textColor}}>
        <Box padding={4} sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center' }}>
          <Typography gutterBottom>
            Dans le cadre du cours de développement mobile de S3 du BUT informatique nous avons réalisé un site de réservation en ligne de matériel de ski avec Android.
          </Typography>
      <Card sx={{width: '20%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={androidmain}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
    </Card>
    <Card sx={{width: '20%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={androidInscription}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
      </Card>
      <Card sx={{width: '20%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={android}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
      </Card>
      <Card sx={{width: '20%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={androidPagePro}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
    </Card>
    <Card sx={{width: '20%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={androidPageProSnow}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
    </Card>
    <Card sx={{width: '20%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={androidConf}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
    </Card>
    <Card sx={{width: '20%', minHeight: '40vh', margin: '0 auto 20px', boxShadow: 'none'}}>
      <CardCover>
        <img
          src={androidCard}
          alt="Harvest"
          loading="lazy"
          style={{ objectFit: 'cover' }}
        />
      </CardCover>
    </Card>
    </Box>
    </DialogContent></>
    )
}