import React from 'react';
import Box from '@mui/material/Box';
import { useTranslation } from 'react-i18next';
import Typography from '@mui/joy/Typography';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { Slide, toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useFormik } from 'formik';
import * as Yup from 'yup';
import emailjs from '@emailjs/browser';

// Composants MUI
import TextField from '@mui/material/TextField';
import { styled } from '@mui/system';
import Button from '@mui/joy/Button';
import Link from '@mui/material/Link';
import Grid from '@mui/material/Grid';
import List from '@mui/material/List';

// Icons
import GitHubIcon from '@mui/icons-material/GitHub';
import CallIcon from '@mui/icons-material/Call';
import EmailIcon from '@mui/icons-material/Email';
import LinkedInIcon from '@mui/icons-material/LinkedIn';
import LocationOnIcon from '@mui/icons-material/LocationOn';

// Contexte & Thèmes
import { useThemeContext } from '../Burger/themeContext';
import themes from './../Burger/theme';
import { dark } from '@mui/material/styles/createPalette';

const Contact = () => {
  const { t } = useTranslation();
  const { darkMode } = useThemeContext();

  // Définition de l'icône pour le Marker de la carte
  const markerIcon = new L.Icon({
    iconUrl:
      'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
    iconSize: [25, 41],
    iconAnchor: [12, 41],
  });

  // Bouton custom conforme au thème
  const CustomButton = styled(Button)({
    backgroundColor: darkMode ? themes.dark.primaryColor : themes.light.primaryColor,
    borderColor: darkMode ? themes.dark.primaryColor : themes.light.primaryColor,
    marginTop: '20px',
    '&:hover': {
      borderColor: '#754de8',
      backgroundColor: '#000000',
    },
  });

  // TextField custom qui adapte sa couleur selon le darkMode
  const CustomTextField = (props) => (
    <TextField
      {...props}
      InputLabelProps={{
        style: { color: darkMode ? themes.dark.text : themes.light.textColor },
      }}
      sx={{
        marginTop: '20px',
        input: { color: darkMode ? themes.dark.text : themes.light.textColor },
        '& .MuiOutlinedInput-root': {
          '& fieldset': {
            borderColor: 'var(--TextField-brandBorderColor)',
          },
          '&:hover fieldset': {
            borderColor: 'var(--TextField-brandBorderHoverColor)',
          },
          '&.Mui-focused fieldset': {
            borderColor: 'var(--TextField-brandBorderFocusedColor)',
          },
        },
      }}
    />
  );

  // Schéma de validation avec Yup
  const validationSchema = Yup.object({
    firstName: Yup.string()
      .max(15, 'Doit être 15 caractères ou moins')
      .required('Champ requis'),
    lastName: Yup.string()
      .max(20, 'Doit être 20 caractères ou moins')
      .required('Champ requis'),
    email: Yup.string()
      .email('Email invalide')
      .required('Champ requis'),
    message: Yup.string().required('Champ requis'),
  });

  // Composant MyForm qui gère le formulaire de contact
  const MyForm = () => {
    const formik = useFormik({
      initialValues: {
        firstName: '',
        lastName: '',
        email: '',
        message: '',
      },
      validationSchema: validationSchema,
      onSubmit: (values) => {
        emailjs
          .send(
            'service_o4il1by',
            'template_n1x56ie',
            values,
            'K7q1JB9_2et-A-NdO'
          )
          .then((response) => {
            console.log('E-mail envoyé avec succès!', response);
            formik.resetForm();
            toast.success('E-mail envoyé avec succès !', {
              position: 'bottom-right',
              autoClose: 5000,
              hideProgressBar: false,
              closeOnClick: true,
              pauseOnHover: true,
              draggable: true,
              theme: darkMode ? 'dark' : 'light',
              transition: Slide,
            });
          })
          .catch((error) => {
            console.error("Erreur lors de l'envoi de l'e-mail:", error);
            toast.error('Une erreur est survenue.', {
              position: 'bottom-right',
              autoClose: 5000,
              hideProgressBar: false,
              closeOnClick: true,
              pauseOnHover: true,
              draggable: true,
              theme: darkMode ? 'dark' : 'light',
              transition: Slide,
            });
          });
      },
    });

    return (
      <>
        <ToastContainer />
        <form onSubmit={formik.handleSubmit}>
          <CustomTextField
            fullWidth
            id="firstName"
            name="firstName"
            label="Prénom *"
            placeholder="Votre prénom"
            value={formik.values.firstName}
            onChange={formik.handleChange}
            error={formik.touched.firstName && Boolean(formik.errors.firstName)}
            helperText={formik.touched.firstName && formik.errors.firstName}
            InputProps={{
              style: {
                color: darkMode ? themes.dark.darker : themes.light.textColor
              } 
            }}
          />
          <CustomTextField
            fullWidth
            id="lastName"
            name="lastName"
            label="Nom *"
            placeholder="Votre nom"
            value={formik.values.lastName}
            onChange={formik.handleChange}
            error={formik.touched.lastName && Boolean(formik.errors.lastName)}
            helperText={formik.touched.lastName && formik.errors.lastName}
            InputProps={{
              style: {
                color: darkMode ? themes.dark.darker : themes.light.textColor
              } 
            }}
          />
          <CustomTextField
            fullWidth
            id="email"
            name="email"
            label="Email *"
            placeholder="votre.email@exemple.com"
            value={formik.values.email}
            onChange={formik.handleChange}
            error={formik.touched.email && Boolean(formik.errors.email)}
            helperText={formik.touched.email && formik.errors.email}
            InputProps={{
              style: {
                color: darkMode ? themes.dark.darker : themes.light.textColor
              } 
            }}
          />
          <CustomTextField
            fullWidth
            id="message"
            name="message"
            label="Message *"
            placeholder="Votre message ..."
            // multiline
            rows={5}
            value={formik.values.message}
            onChange={formik.handleChange}
            error={formik.touched.message && Boolean(formik.errors.message)}
            helperText={formik.touched.message && formik.errors.message}
            InputProps={{
              style: {
                color: darkMode ? themes.dark.darker : themes.light.textColor
              } 
            }}
          />
          <CustomButton type="submit" size="lg" variant="solid">
            Envoyer
          </CustomButton>
        </form>
      </>
    );
  };

  return (
    <Box
      component="main"
      sx={{
        flexGrow: 1,
        py: 5,
        px: { xs: 2, sm: 4, md: 8 },
        backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
        color: darkMode ? 'white' : '#000000',
        minHeight: '100vh',
      }}
    >
      {/* Conteneur principal */}
      <Box
        sx={{
          maxWidth: '1200px',
          margin: '0 auto',
          backgroundColor: darkMode ? themes.dark.encadre : themes.light.encadre,
          borderRadius: '10px',
          padding: { xs: '20px', md: '40px' },
        }}
      >
        {/* Titre */}
        <Typography
          variant="h2"
          sx={{
            color: darkMode ? themes.dark.text : themes.light.textColor,
            textAlign: 'center',
            marginBottom: '4%',
            fontSize: { xs: '2rem', md: '2.6rem' },
          }}
        >
          {t('CONTACT')}
        </Typography>
        {/* Grille à deux colonnes : Formulaire et Informations de contact */}
        <Grid container spacing={4}>
          {/* Colonne gauche : Formulaire via MyForm */}
          <Grid item xs={12} md={6}>
            <Typography
              variant="h5"
              sx={{
                color: darkMode ? themes.dark.text : themes.light.textColor,
                marginBottom: '20px',
                fontWeight: 'bold',
              }}
            >
              Envoyez-moi un message
            </Typography>
            <MyForm />
          </Grid>

          {/* Colonne droite : Informations de contact et carte */}
          <Grid item xs={12} md={6}>
            <Typography
              variant="h5"
              sx={{
                color: darkMode ? themes.dark.text : themes.light.textColor,
                marginBottom: '20px',
                fontWeight: 'bold',
              }}
            >
              Informations de contact
            </Typography>

            {/* Informations (Email, Téléphone, Localisation) */}
            <Box sx={{ marginBottom: '20px' }}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <EmailIcon sx={{ mr: 1 }} />
                <Typography sx={{ color: darkMode ? themes.dark.text : themes.light.textColor }}>
                  louise.sanchez62@gmail.com
                </Typography>
              </Box>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <LocationOnIcon sx={{ mr: 1 }} />
                <Typography sx={{ color: darkMode ? themes.dark.text : themes.light.textColor }}>
                  Valbonne, Sophia Antipolis
                </Typography>
              </Box>
            </Box>

            {/* Réseaux sociaux */}
            <Typography variant="h6" sx={{ color: darkMode ? themes.dark.text : themes.light.textColor, marginBottom: '10px', fontWeight: 'bold' }}>
              Réseaux sociaux
            </Typography>
            <List sx={{ display: 'flex', gap: '10px', marginBottom: '30px' }}>
              <Link href="https://github.com/" target="_blank" rel="noopener noreferrer" sx={{ color: 'inherit' }}>
                <GitHubIcon />
              </Link>
              <Link href="https://www.linkedin.com/" target="_blank" rel="noopener noreferrer" sx={{ color: 'inherit' }}>
                <LinkedInIcon />
              </Link>
              {/* D'autres icônes peuvent être ajoutées ici */}
            </List>

            {/* Carte affichant la localisation */}
            <Box sx={{ borderRadius: '10px', overflow: 'hidden' }}>
              <MapContainer
                center={[43.6167, 7.0667]}
                zoom={15}
                style={{ height: '300px', width: '100%' }}
              >
                <TileLayer
                  url={
                    darkMode
                      ? 'https://{s}.tile.openstreetmap.fr/osmfr/{z}/{x}/{y}.png'
                      : 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'
                  }
                  attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                />
                <Marker position={[43.6167, 7.0667]} icon={markerIcon}>
                  <Popup>
                    Université Côte d'Azur - Campus Sophia Tech
                  </Popup>
                </Marker>
              </MapContainer>
            </Box>
          </Grid>
        </Grid>
      </Box>
    </Box>
  );
};

export default Contact;
