import React from 'react';
import { Box, Card, CardContent, Typography, Button, Grid, Chip, Avatar, Stack } from '@mui/material';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import science from '../../img/science.jpg';
import cannesIA from '../../img/cannesIA.jpg';
import GOW from '../../img/GOW.jpg';
import rivieraJUG from '../../img/rivieraJUG.jpg';

function Extracurricular() {
  const { darkMode } = useThemeContext();

  const events = [
    {
      title: "Fête de la Science",
      location: "Juan-les-Pins",
      date: "Annuel",
      description: "Participation active chaque année pour vulgariser les sciences et découvrir les dernières innovations locales.",
      tag: "Vulgarisation",
      image: science,
      hasMore: false,
    },
    {
      title: "Riviera JUG NAT",
      location: "Sophia Antipolis",
      date: "Éditions passées & futures",
      description: "Conférences techniques sur l'écosystème Java et les nouvelles technologies. Une immersion riche que je compte renouveler.",
      tag: "Conférence Tech",
      image: rivieraJUG,
      hasMore: false,
    },
    {
      title: "World AI Cannes Festival",
      location: "Palais des Festivals, Cannes",
      date: "Journée Grand Public",
      description: "Exploration des avancées mondiales en IA, de l'éthique aux applications concrètes de demain.",
      tag: "Intelligence Artificielle",
      image: cannesIA,
      hasMore: false,
    },
    {
      title: "Games on Web",
      location: "Université Côte d'Azur",
      date: "Thème : Dream Land",
      description: "Hackathon de développement de jeux web. Création d'une expérience interactive autour de l'imaginaire des rêves.",
      tag: "Hackathon / Web",
      image: GOW,
      hasMore: true,
    }
  ];

  const cardBg = darkMode ? themes.dark.cardBackgroundColor : themes.light.cardBackgroundColor;

  return (
    <Box sx={{
      height: '100vh',
      overflowY: 'auto',
      backgroundColor: darkMode ? themes.dark.backgroundColor : themes.light.backgroundColor,
      p: 4,
      scrollbarWidth: 'none',
      '&::-webkit-scrollbar': { display: 'none' },
    }}>
      
      <Typography variant="h3" textAlign="center" sx={{ mb: 6, fontWeight: 'bold', color: darkMode ? '#fff' : '#000' }}>
        Expériences Extracurriculaires
      </Typography>

      {/* Stack remplace la Grid pour empiler verticalement avec un espacement (spacing) */}
      <Stack spacing={4} alignItems="center" sx={{ width: '100%', pb: 10 }}>
        
        {events.map((event, index) => (
          <Card 
            key={index}
            sx={{ 
              display: 'flex', 
              flexDirection: 'row', // Image à côté du texte
              width: '100%', 
              maxWidth: '900px', // Contrôle la "longueur" de la carte
              minHeight: '280px',
              backgroundColor: cardBg,
              borderRadius: '20px',
              overflow: 'hidden', // Pour que l'image respecte les arrondis
              transition: 'transform 0.3s ease',
              '&:hover': { transform: 'scale(1.02)' }
            }}
          >
            {/* Zone de Texte : on lui donne plus d'espace (flex: 1.5 ou 2) */}
            <Box sx={{ flex: 1.5, p: 4, display: 'flex', flexDirection: 'column' }}>
              <Box>
                <Chip 
                  label={event.tag} 
                  size="small" 
                  sx={{ mb: 2, backgroundColor: '#e3f2fd', color: darkMode ? themes.dark.darker : themes.light.primaryColor, fontWeight: 'bold' }} 
                />
                <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 1, color: '#fff' }}>
                  {event.title}
                </Typography>
                <Typography variant="body1" sx={{ color: darkMode ? themes.dark.primaryColor : themes.light.primaryColor, mb: 2, display: 'flex', alignItems: 'center' }}>
                  <span style={{ marginRight: '8px' }}>📍</span> {event.location}
                </Typography>
              </Box>

              <Typography variant="body1" sx={{ color: 'rgba(255,255,255,0.8)', lineHeight: 1.7, mb: 3 }}>
                {event.description}
              </Typography>

              <Box sx={{ mt: 'auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Typography variant="h6" sx={{ color: '#fff', opacity: 0.9 }}>
                  {event.date}
                </Typography>
                {event.hasMore && (
                  <Button 
                    variant="outlined" 
                    endIcon={<ArrowForwardIcon />}
                    sx={{ 
                      borderRadius: '25px', 
                      color: '#fff', 
                      borderColor: 'rgba(255,255,255,0.3)',
                      textTransform: 'none',
                      px: 3
                    }}
                  >
                    En savoir plus
                  </Button>
                )}
              </Box>
            </Box>

            {/* Zone Image : rectangulaire, angles arrondis à droite */}
            <Box
              sx={{
                flex: 1,
                backgroundImage: `url(${event.image})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                borderLeft: '1px solid rgba(255,255,255,0.1)',
                // On peut ajouter un margin pour que l'image paraisse "incrustée"
                m: 1.5,
                borderRadius: '15px' 
              }}
            />
          </Card>
        ))}
        
      </Stack>
    </Box>
  );
}

export default Extracurricular;