import React from 'react';
import Box from '@mui/material/Box';
import Button from '@mui/joy/Button';
import Card from '@mui/joy/Card';
import CardCover from '@mui/joy/CardCover';
import CardContent from '@mui/joy/CardContent';
import Typography from '@mui/joy/Typography';
import LocationOnRoundedIcon from '@mui/icons-material/LocationOnRounded';
import { useTranslation } from 'react-i18next'; // Garder une seule fois
import { styled } from '@mui/system';
import { useThemeContext } from '../Burger/themeContext';
import themes from '../Burger/theme';
import espagne from './../../img/espagne-portfolio.jpg';

// Définition du bouton
const CustomOutlinedButton = styled(Button)(({ theme }) => ({
  borderColor: themes.dark.primaryColor,
  color: themes.dark.primaryColor,
  '&:hover': {
    borderColor: '#754de8',
    backgroundColor: 'rgba(0,0,0,0.1)',
  },
}));

function Bienvenue({ onNext }) { // Ajout de la prop onNext pour le scroll
  const { darkMode } = useThemeContext();
  const { t } = useTranslation();

  return (
    <Box sx={{ padding: '4%', margin:'3%' }}>
      <Box sx={{ 
          display: 'flex', 
          flexWrap: 'wrap', 
          justifyContent: 'space-between', 
          bgcolor: darkMode ? themes.dark.encadre : themes.light.encadre, 
          borderRadius: '10px', 
      }}>
        <Box sx={{ width: { sm: '70%', md: '55%' } }}>
          <Typography sx={{ fontSize: '2.6rem', fontFamily: '"Comfortaa", sans-serif', color: darkMode ? themes.dark.textTitle : themes.light.textColor }}>
            {t('BIENVENUE')}
          </Typography>
          <Typography sx={{ fontSize: '1.2rem', color: darkMode ? themes.dark.text : themes.light.textColor }}>
            {t('PRESENTATION')}
          </Typography>
          <br />
          <CustomOutlinedButton size="lg" variant="outlined" onClick={onNext}>
            {t('BUTTON')}
          </CustomOutlinedButton>
        </Box>
        
        <Card sx={{ minHeight: '400px', width: 320, border: 'none' }}>
          <CardCover>
            <img src={espagne} loading="lazy" alt="Espagne" />
          </CardCover>
          <CardContent sx={{ justifyContent: 'flex-end' }}>
            <Typography level="title-lg" textColor="#fff">28/07/2025</Typography>
            <Typography startDecorator={<LocationOnRoundedIcon />} textColor="neutral.300">Barcelone</Typography>
          </CardContent>
        </Card>
      </Box>
    </Box>
  );
}

export default Bienvenue;